 public function __construct(private$db=null,private?PaymentComplementPreflightService$preflight=null,private?PaymentComplementFiscalDocumentService$documents=null,private?CfdiSigningService$signer=null,private?FiscalStampingService$pac=null){$this->db??=db_connect();$this->preflight??=new PaymentComplementPreflightService($this->db);$this->documents??=new PaymentComplementFiscalDocumentService($this->db);$this->signer??=new CfdiSigningService($this->db);$this->pac??=new FiscalStampingService($this->db);}
 public function stamp(int$id,int$userId,bool$authorized):array{if(!$authorized)throw new RuntimeException('No tiene permiso para timbrar Complementos.');$lock='payment_complement_stamp_'.$id;$got=(int)($this->db->query('SELECT GET_LOCK(?,0) acquired',[$lock])->getRow()->acquired??0);if($got!==1)throw new RuntimeException('El Complemento ya está siendo procesado.');try{$header=$this->db->table('payment_complements')->where(['id'=>$id,'deleted'=>0])->get(1)->getRow();if(!$header)throw new RuntimeException('El Complemento no existe.');if($header->status==='stamped'){return$this->existing($header);} $inspection=$this->preflight->requireReady($id);$materialized=$this->documents->materialize($id,$inspection['snapshot'],$userId);$documentId=(int)$materialized['document_id'];$persistedStamp=$this->db->table('fiscal_document_stamps')->where('fiscal_document_id',$documentId)->get(1)->getRow();if($persistedStamp&&!empty($persistedStamp->uuid)){$this->db->table('payment_complements')->where('id',$id)->update(['status'=>'stamped','stamped_at'=>$persistedStamp->stamp_date??get_current_utc_time(),'last_stamp_error'=>null,'updated_at'=>get_current_utc_time()]);$header->status='stamped';$header->fiscal_document_id=$documentId;return$this->existing($header);}$signature=$this->db->table('fiscal_document_signatures')->where(['fiscal_document_id'=>$documentId,'signature_verified'=>1,'xsd_status'=>'valid'])->orderBy('id','DESC')->get(1)->getRow();if(!$signature){$certificate=$this->activeCertificate($documentId);$this->signer->sign($documentId,(int)$materialized['artifact']->id,(int)$certificate->id,$userId,true);}$result=$this->pac->stamp($documentId,$userId,true);if($result->xmlAvailable&&$result->uuid){$stamp=$this->db->table('fiscal_document_stamps')->where('fiscal_document_id',$documentId)->get(1)->getRow();$pdfAvailable=$result->pdfAvailable;if(!$pdfAvailable){try{$pdf=(new FiscalPacPdfGenerationService($this->db))->generate($documentId,$userId);$pdfAvailable=(bool)$pdf->pdfAvailable;}catch(Throwable $pdfError){log_message('warning','Payment Complement PDF pending for document {id}: {type}',['id'=>$documentId,'type'=>get_class($pdfError)]);}}$this->db->table('payment_complements')->where('id',$id)->update(['status'=>'stamped','stamped_at'=>$stamp->stamp_date??get_current_utc_time(),'last_stamp_error'=>null,'updated_at'=>get_current_utc_time()]);return['success'=>true,'status'=>'stamped','uuid'=>$result->uuid,'document_id'=>$documentId,'attempt_id'=>$result->attemptId,'xml_available'=>true,'pdf_available'=>$pdfAvailable,'message'=>'Complemento timbrado correctamente.'];}$message=trim((string)($result->providerMessage??'El PAC no aceptó el Complemento.'));$this->db->table('payment_complements')->where('id',$id)->update(['status'=>'complete_draft','last_stamp_error'=>mb_substr($message,0,2000),'updated_at'=>get_current_utc_time()]);return['success'=>false,'status'=>$result->status,'uuid'=>null,'document_id'=>$documentId,'attempt_id'=>$result->attemptId,'xml_available'=>false,'pdf_available'=>false,'retryable'=>$result->retryable,'requires_reconciliation'=>$result->requiresReconciliation,'code'=>$result->providerCode,'message'=>$message];}catch(Throwable$e){$this->db->table('payment_complements')->where('id',$id)->update(['last_stamp_error'=>mb_substr($e->getMessage(),0,2000),'updated_at'=>get_current_utc_time()]);throw$e;}finally{$this->db->query('SELECT RELEASE_LOCK(?)',[$lock]);}}
 private function activeCertificate(int$documentId):object{$d=$this->db->table('fiscal_documents')->where('id',$documentId)->get(1)->getRow();$now=get_current_utc_time();$c=$this->db->table('fiscal_issuer_certificates')->where(['issuer_profile_id'=>$d->issuer_profile_id,'status'=>'valid','deleted'=>0])->where('valid_from <=',$now)->where('valid_to >=',$now)->orderBy('valid_to','DESC')->get(1)->getRow();if(!$c)throw new RuntimeException('El emisor no tiene un CSD utilizable.');return$c;}
